package com.punjab.oms.ar.dao.finance.impl;
import com.punjab.oms.ar.dao.finance.SettlementDao;import com.punjab.oms.ar.domain.entity.finance.*;import com.punjab.oms.ar.mapper.finance.*;
import com.baomidou.mybatisplus.extension.repository.CrudRepository;import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.baomidou.mybatisplus.core.conditions.update.LambdaUpdateWrapper;
import org.springframework.stereotype.Repository;import lombok.RequiredArgsConstructor;import java.util.List;
/** 同一事务内按稳定顺序锁定资金与应收。 @author Punjab */
@Repository @RequiredArgsConstructor
public class SettlementDaoImpl extends CrudRepository<ArSettlementMapper,ArSettlement> implements SettlementDao {
 private final ArReceiptMapper receipts;private final ArGroupMapper groups;private final ArLineMapper lines;private final ArSettlementAllocationMapper allocations;private final ArEventMapper events;
 public ArReceipt receipt(Long id,Long entity,boolean lock){var q=new LambdaQueryWrapper<ArReceipt>().eq(ArReceipt::getId,id).eq(ArReceipt::getLegalEntityId,entity).eq(ArReceipt::getDeleteStatus,false);if(lock)q.last("FOR UPDATE");return receipts.selectOne(q);}
 public List<ArGroup> groups(List<Long> ids,Long entity,boolean lock){var q=new LambdaQueryWrapper<ArGroup>().in(ArGroup::getId,ids).eq(ArGroup::getLegalEntityId,entity).eq(ArGroup::getDeleteStatus,false).orderByAsc(ArGroup::getId);if(lock)q.last("FOR UPDATE");return groups.selectList(q);}
 public List<ArLine> groupLines(List<Long> ids,boolean lock){var q=new LambdaQueryWrapper<ArLine>().in(ArLine::getGroupId,ids).eq(ArLine::getStatus,"ACTIVE").eq(ArLine::getDeleteStatus,false).gt(ArLine::getReceivableAmount,0).orderByAsc(ArLine::getId);if(lock)q.last("FOR UPDATE");return lines.selectList(q);}
 public List<ArLine> linesByIds(List<Long> ids,boolean lock){var q=new LambdaQueryWrapper<ArLine>().in(ArLine::getId,ids).eq(ArLine::getDeleteStatus,false).orderByAsc(ArLine::getId);if(lock)q.last("FOR UPDATE");return lines.selectList(q);}
 public boolean updateReceipt(ArReceipt v,Long expected){return receipts.update(null,new LambdaUpdateWrapper<ArReceipt>().eq(ArReceipt::getId,v.getId()).eq(ArReceipt::getVersion,expected).eq(ArReceipt::getDeleteStatus,false).set(ArReceipt::getAllocatedAmount,v.getAllocatedAmount()).set(ArReceipt::getVersion,v.getVersion()).set(ArReceipt::getUpdatedBy,v.getUpdatedBy()).set(ArReceipt::getUpdatedTime,v.getUpdatedTime()))==1;}
 public boolean updateLine(ArLine v,Long expected){return lines.update(null,new LambdaUpdateWrapper<ArLine>().eq(ArLine::getId,v.getId()).eq(ArLine::getVersion,expected).eq(ArLine::getStatus,"ACTIVE").eq(ArLine::getDeleteStatus,false).set(ArLine::getSettledAmount,v.getSettledAmount()).set(ArLine::getOpenAmount,v.getOpenAmount()).set(ArLine::getVersion,v.getVersion()).set(ArLine::getUpdatedBy,v.getUpdatedBy()).set(ArLine::getUpdatedTime,v.getUpdatedTime()))==1;}
 public boolean create(ArSettlement value){return baseMapper.insert(value)==1;}
 public boolean update(ArSettlement v,Long expected){return baseMapper.update(null,new LambdaUpdateWrapper<ArSettlement>().eq(ArSettlement::getId,v.getId()).eq(ArSettlement::getVersion,expected).eq(ArSettlement::getDeleteStatus,false).set(ArSettlement::getStatus,v.getStatus()).set(ArSettlement::getVersion,v.getVersion()).set(ArSettlement::getUpdatedBy,v.getUpdatedBy()).set(ArSettlement::getUpdatedTime,v.getUpdatedTime()))==1;}
 public boolean allocate(ArSettlementAllocation value){return allocations.insert(value)==1;}
 public ArSettlement settlement(Long id,Long entity,boolean lock){var q=new LambdaQueryWrapper<ArSettlement>().eq(ArSettlement::getId,id).eq(ArSettlement::getLegalEntityId,entity).eq(ArSettlement::getDeleteStatus,false);if(lock)q.last("FOR UPDATE");return baseMapper.selectOne(q);}
 public List<ArSettlementAllocation> allocations(Long id){return allocations.selectList(new LambdaQueryWrapper<ArSettlementAllocation>().eq(ArSettlementAllocation::getSettlementId,id).eq(ArSettlementAllocation::getDeleteStatus,false).orderByAsc(ArSettlementAllocation::getSequenceNo));}
 public Long postedEvent(Long id){var event=events.selectOne(new LambdaQueryWrapper<ArEvent>().in(ArEvent::getEventType,List.of("RECEIPT_SETTLED","OFFSET_SETTLED")).eq(ArEvent::getTriggerType,"SETTLEMENT").eq(ArEvent::getTriggerId,id.toString()).eq(ArEvent::getDeleteStatus,false));return event==null?null:event.getId();}
}
